package io.aetheris.orchestrator.stage9;
import jakarta.persistence.*;import java.time.Instant;import java.util.*;import java.util.stream.Collectors;
@Entity @Table(name="aetheris_stage9_work_requirements")
public class WorkRequirementEntity {@Id private UUID workItemId;@Column(nullable=false,length=2000) private String capabilitiesCsv;@Column(nullable=false,length=80) private String lane;@Column(nullable=false) private Instant updatedAt;protected WorkRequirementEntity(){}public WorkRequirementEntity(UUID id,Set<String> caps,String lane){workItemId=id;update(caps,lane);}public UUID getWorkItemId(){return workItemId;}public String getLane(){return lane;}public Instant getUpdatedAt(){return updatedAt;}public Set<String> getCapabilities(){if(capabilitiesCsv==null||capabilitiesCsv.isBlank())return Set.of();return Arrays.stream(capabilitiesCsv.split(",")).map(String::trim).filter(x->!x.isBlank()).collect(Collectors.toCollection(LinkedHashSet::new));}public void update(Set<String> caps,String lane){capabilitiesCsv=caps==null?"":caps.stream().filter(Objects::nonNull).map(String::trim).filter(x->!x.isBlank()).map(String::toLowerCase).distinct().sorted().collect(Collectors.joining(","));this.lane=lane==null||lane.isBlank()?"default":lane.trim().toLowerCase(Locale.ROOT);updatedAt=Instant.now();}}
